package com.nigson.commerce.quote;

import java.math.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.commerce.pricing.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;

/** Commerce-owned quote persistence. Revisions and their lines are append-only snapshots. */
public final class JdbcQuoteRepository implements QuoteRepository {
 private final JdbcTemplate jdbc;private final PricingAuthority authority;private final Pricing pricing;private final Clock clock;
 public JdbcQuoteRepository(JdbcTemplate jdbc,PricingAuthority authority,Pricing pricing,Clock clock){this.jdbc=jdbc;this.authority=authority;this.pricing=pricing;this.clock=clock;}
 private static Problem.Failure rule(){return new Problem.Failure(ProblemCode.QUOTE_RULE_VIOLATION);}
 private static void version(long v){if(v<0||v==Long.MAX_VALUE)throw ApiValues.invalid();}
 private void validMarket(UUID market){if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.market m JOIN commerce.currency c ON c.code=m.currency_code WHERE m.id=? AND m.code='NG' AND m.currency_code='NGN' AND m.enabled AND c.active AND c.minor_unit=2)",Boolean.class,market)))throw rule();}
 private void validParty(UUID party,UUID organization){if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.party WHERE id=? AND status='ACTIVE')",Boolean.class,party)))throw new Problem.Failure(ProblemCode.NOT_FOUND);if(organization!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.organization_membership m JOIN commerce.organization o ON o.id=m.organization_id WHERE m.organization_id=? AND m.party_id=? AND m.status='ACTIVE' AND o.status='ACTIVE')",Boolean.class,organization,party)))throw rule();}
 private BigDecimal lines(UUID market,UUID organization,List<QuoteValues.LineInput> items){
  if(items==null||items.isEmpty()||items.size()>100)throw ApiValues.invalid();Instant now=clock.instant();BigDecimal total=BigDecimal.ZERO.setScale(2);for(var line:items){BigDecimal qty=new BigDecimal(line.quantity()),unit=new BigDecimal(line.agreedUnitAmount()),discount=new BigDecimal(line.discountAmount()),tax=new BigDecimal(line.taxAmount());if(qty.signum()<=0||qty.scale()>3||unit.signum()<0||unit.scale()>2||discount.signum()<0||discount.scale()>2||tax.signum()<0||tax.scale()>2||discount.compareTo(qty.multiply(unit).setScale(2,RoundingMode.HALF_UP))>0)throw rule();var resolved=pricing.resolve(line.skuId(),qty,market,organization,now,now.plusSeconds(300),true);if(resolved==null||resolved.unitAmount()==null||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.product_market_eligibility e JOIN commerce.sku s ON s.product_id=e.product_id JOIN commerce.product p ON p.id=s.product_id WHERE s.id=? AND s.active AND s.deleted_at IS NULL AND p.status='ACTIVE' AND p.deleted_at IS NULL AND e.market_id=? AND e.eligible)",Boolean.class,line.skuId(),market)))throw rule();BigDecimal value=qty.multiply(unit).setScale(2,RoundingMode.HALF_UP).subtract(discount).add(tax).setScale(2,RoundingMode.HALF_UP);if(value.signum()<0)throw rule();total=total.add(value);}if(total.precision()>17)throw rule();return total;}
 private void saveLines(UUID revision,List<QuoteValues.LineInput> items,String actor){for(var line:items)jdbc.update("INSERT INTO commerce.quote_line(id,created_by,updated_by,revision_id,sku_id,quantity,agreed_unit_amount,discount_amount,tax_amount) VALUES (?,?,?,?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),actor,actor,revision,line.skuId(),new BigDecimal(line.quantity()),new BigDecimal(line.agreedUnitAmount()),new BigDecimal(line.discountAmount()),new BigDecimal(line.taxAmount()));}
 @Override public QuoteValues.Quote create(ActorAssertion.Actor actor,QuoteValues.CreateInput input,String actorId){if(!input.validUntil().isAfter(clock.instant()))throw rule();validMarket(input.marketId());validParty(input.partyId(),input.organizationId());UUID id=EventCodec.uuid7(clock.instant()),revisionId=EventCodec.uuid7(clock.instant());BigDecimal total=lines(input.marketId(),input.organizationId(),input.lines());jdbc.update("INSERT INTO commerce.quote(id,created_by,updated_by,party_id,organization_id,market_id,source_lead_id,status) VALUES (?,?,?,?,?,?,?,'DRAFT')",id,actorId,actorId,input.partyId(),input.organizationId(),input.marketId(),input.sourceLeadId());jdbc.update("INSERT INTO commerce.quote_revision(id,created_by,updated_by,quote_id,revision,currency_code,valid_until,terms,approval_status,total) VALUES (?,?,?, ?,1,'NGN',?,?,'DRAFT',?)",revisionId,actorId,actorId,id,Timestamp.from(input.validUntil()),input.terms(),total);saveLines(revisionId,input.lines(),actorId);jdbc.update("UPDATE commerce.quote SET current_revision_id=? WHERE id=?",revisionId,id);return getById(id,false);}
 @Override public QuoteValues.Quote revise(ActorAssertion.Actor actor,UUID id,long expected,QuoteValues.RevisionInput input,String actorId){version(expected);if(!input.validUntil().isAfter(clock.instant()))throw rule();var rows=jdbc.queryForList("SELECT q.*,r.revision FROM commerce.quote q JOIN commerce.quote_revision r ON r.id=q.current_revision_id WHERE q.id=? FOR UPDATE OF q",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var q=rows.getFirst();editable(actor,q,expected);if(Set.of("ACCEPTED","REJECTED","EXPIRED","CANCELLED").contains(q.get("status")))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);int next=((Number)q.get("revision")).intValue()+1;UUID revisionId=EventCodec.uuid7(clock.instant());UUID market=(UUID)q.get("market_id"),organization=(UUID)q.get("organization_id");BigDecimal total=lines(market,organization,input.lines());jdbc.update("INSERT INTO commerce.quote_revision(id,created_by,updated_by,quote_id,revision,currency_code,valid_until,terms,approval_status,total) VALUES (?,?,?, ?,?,'NGN',?,?,'DRAFT',?)",revisionId,actorId,actorId,id,next,Timestamp.from(input.validUntil()),input.terms(),total);saveLines(revisionId,input.lines(),actorId);int changed=jdbc.update("UPDATE commerce.quote SET current_revision_id=?,status='DRAFT',version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=?",revisionId,Timestamp.from(clock.instant()),actorId,id,expected);if(changed!=1)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);return getById(id,false);}
 @Override public QuoteValues.Quote approve(ActorAssertion.Actor actor,UUID id,UUID revision,long expected,QuoteValues.Decision input,String actorId){version(expected);var rows=jdbc.queryForList("SELECT q.*,r.revision,r.created_by AS revision_creator,r.approval_status FROM commerce.quote q JOIN commerce.quote_revision r ON r.id=q.current_revision_id WHERE q.id=? AND r.id=? FOR UPDATE OF q,r",id,revision);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var q=rows.getFirst();editable(actor,q,expected);if(!"DRAFT".equals(q.get("status"))||!"DRAFT".equals(q.get("approval_status"))||actorId.equals(q.get("revision_creator")))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);jdbc.update("UPDATE commerce.quote_revision SET approval_status=?,approved_by=?,updated_at=?,updated_by=?,version=version+1 WHERE id=? AND approval_status='DRAFT'",input.approve()?"APPROVED":"REJECTED",actor.party(),Timestamp.from(clock.instant()),actorId,revision);if(jdbc.update("UPDATE commerce.quote SET version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=?",Timestamp.from(clock.instant()),actorId,id,expected)!=1)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);return getById(id,false);}
 @Override public QuoteValues.Quote offer(ActorAssertion.Actor actor,UUID id,long expected,QuoteValues.Offer input,String actorId){version(expected);var rows=jdbc.queryForList("SELECT q.*,r.revision,r.approval_status,r.valid_until FROM commerce.quote q JOIN commerce.quote_revision r ON r.id=q.current_revision_id WHERE q.id=? AND r.id=? FOR UPDATE OF q,r",id,input.revisionId());if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var q=rows.getFirst();editable(actor,q,expected);if(!"DRAFT".equals(q.get("status"))||!"APPROVED".equals(q.get("approval_status"))||!((Timestamp)q.get("valid_until")).toInstant().isAfter(clock.instant()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(jdbc.update("UPDATE commerce.quote SET status='OFFERED',version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=?",Timestamp.from(clock.instant()),actorId,id,expected)!=1)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);return getById(id,false);}
 private void editable(ActorAssertion.Actor actor,Map<String,Object> q,long expected){if(((Number)q.get("version")).longValue()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);}
 @Override public QuoteValues.Quote get(ActorAssertion.Actor actor,UUID id){authority.require(actor,"CUSTOMER");var rows=jdbc.queryForList("SELECT party_id,organization_id FROM commerce.quote WHERE id=?",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var q=rows.getFirst();UUID organization=(UUID)q.get("organization_id");if(!actor.party().equals(q.get("party_id"))){if(organization==null)throw new Problem.Failure(ProblemCode.NOT_FOUND);authority.organization(actor,organization,false);}else if(organization!=null)authority.organization(actor,organization,false);return getById(id,false);}
 @Override public QuoteValues.Quote current(UUID id){return getById(id,false);}
 @Override public void requireOwner(ActorAssertion.Actor actor,UUID id){authority.require(actor,"CUSTOMER");var rows=jdbc.queryForList("SELECT party_id,organization_id FROM commerce.quote WHERE id=?",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var q=rows.getFirst();UUID organization=(UUID)q.get("organization_id");if(!actor.party().equals(q.get("party_id"))){if(organization==null)throw new Problem.Failure(ProblemCode.NOT_FOUND);authority.organization(actor,organization,false);}else if(organization!=null)authority.organization(actor,organization,false);}
 @Override public QuoteValues.Quote owned(UUID id,UUID revision,ActorAssertion.Actor actor,boolean lock){authority.require(actor,"CUSTOMER");var rows=jdbc.queryForList("SELECT q.party_id,q.organization_id,q.market_id,q.status,q.current_revision_id,q.version,r.valid_until,r.approval_status FROM commerce.quote q JOIN commerce.quote_revision r ON r.id=? WHERE q.id=? AND r.quote_id=q.id"+(lock?" FOR UPDATE OF q,r":""),revision,id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var q=rows.getFirst();if(!actor.party().equals(q.get("party_id"))){UUID organization=(UUID)q.get("organization_id");if(organization==null)throw new Problem.Failure(ProblemCode.NOT_FOUND);authority.organization(actor,organization,lock);}if(!"OFFERED".equals(q.get("status"))||!revision.equals(q.get("current_revision_id"))||!"APPROVED".equals(q.get("approval_status"))||!((Timestamp)q.get("valid_until")).toInstant().isAfter(clock.instant()))throw rule();return getById(id,lock);}
 private QuoteValues.Quote getById(UUID id,boolean lock){var rows=jdbc.query("SELECT q.id,q.status,q.current_revision_id,q.version,r.revision,r.total,r.currency_code,r.valid_until FROM commerce.quote q JOIN commerce.quote_revision r ON r.id=q.current_revision_id WHERE q.id=?"+(lock?" FOR SHARE OF q,r":""),(r,n)->new Object[]{r.getObject(1,UUID.class),r.getString(2),r.getObject(3,UUID.class),r.getLong(4),r.getInt(5),r.getBigDecimal(6).toPlainString(),r.getString(7),r.getTimestamp(8).toInstant()},id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var q=rows.getFirst();UUID revision=(UUID)q[2];var items=jdbc.query("SELECT id,sku_id,quantity,agreed_unit_amount,discount_amount,tax_amount FROM commerce.quote_line WHERE revision_id=? ORDER BY sku_id",(r,n)->{BigDecimal qty=r.getBigDecimal(3),unit=r.getBigDecimal(4),discount=r.getBigDecimal(5),tax=r.getBigDecimal(6);String lineTotal=qty.multiply(unit).setScale(2,RoundingMode.HALF_UP).subtract(discount).add(tax).setScale(2,RoundingMode.HALF_UP).toPlainString();return new QuoteValues.Line(r.getObject(1,UUID.class),r.getObject(2,UUID.class),qty.stripTrailingZeros().toPlainString(),unit.toPlainString(),discount.toPlainString(),tax.toPlainString(),lineTotal);},revision);return new QuoteValues.Quote((UUID)q[0],(String)q[1],revision,(Integer)q[4],(String)q[5],(String)q[6],(Instant)q[7],List.copyOf(items),(Long)q[3]);}
}
